-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id,
        gp_business_key,
        gp_record_id,
        gp_source_id,
        gp_name,
        gp_domicile,
        gp_relationship_start_on,
        gp_reported_on,
        violation_00,
        violation_01
    from {{ ref("investment__gp_vault__checked_post") }}
),
violations as (
    select
        'gp_business_key_not_null' as rule_name,
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id,
        gp_business_key,
        gp_record_id,
        gp_source_id,
        gp_name,
        gp_domicile,
        gp_relationship_start_on,
        gp_reported_on
    from quarantined
    where violation_00

    union all

    select
        'gp_business_key_unique' as rule_name,
        gp_source_system,
        gp_identity_key,
        gp_normalised_name,
        gp_lei,
        gp_external_id,
        gp_business_key,
        gp_record_id,
        gp_source_id,
        gp_name,
        gp_domicile,
        gp_relationship_start_on,
        gp_reported_on
    from quarantined
    where violation_01
)

select
    rule_name,
    gp_source_system,
    gp_identity_key,
    gp_normalised_name,
    gp_lei,
    gp_external_id,
    gp_business_key,
    gp_record_id,
    gp_source_id,
    gp_name,
    gp_domicile,
    gp_relationship_start_on,
    gp_reported_on
from violations
